```python
import griffe

api = griffe.load("requests")

names = []
for name, member in api.members.items():
    if name.startswith("_"):
        continue
    try:
        if member.is_function and member.is_public:
            names.append(name)
    except griffe.AliasResolutionError:
        continue

for name in sorted(names):
    print(name)
